//! Termination and read-accounting guarantees for the local profile.
//! The fixtures are generated by `fixtures/tail_fixture.py` and stay under 2 MiB.
use scan_core::{Profile, ReadAt, Result, ScanError, ScanLimits, ScanResult, Status, scan_with_limits};
use std::{
    future::Future,
    pin::pin,
    task::{Context, Poll, Waker},
};

struct Counting<'a> {
    data: &'a [u8],
    requested: u64,
    reads: u64,
}

impl ReadAt for Counting<'_> {
    fn size(&self) -> u64 {
        self.data.len() as u64
    }
    async fn read_at(&mut self, offset: u64, len: usize) -> Result<Vec<u8>> {
        self.requested += len as u64;
        self.reads += 1;
        self.data
            .get(offset as usize..offset as usize + len)
            .map(<[u8]>::to_vec)
            .ok_or(ScanError::Invalid("fixture range"))
    }
}

fn ready<T>(f: impl Future<Output = T>) -> T {
    match pin!(f).poll(&mut Context::from_waker(Waker::noop())) {
        Poll::Ready(value) => value,
        Poll::Pending => panic!("in-memory I/O must be immediately ready"),
    }
}

fn local(data: &[u8]) -> (ScanResult, Counting<'_>) {
    let mut source = Counting { data, requested: 0, reads: 0 };
    let result = ready(scan_with_limits(&mut source, ScanLimits::for_profile(Profile::Local)));
    (result, source)
}

#[test]
fn compressed_nested_disk_image_is_not_replayed_per_backward_jump() {
    let data = include_bytes!("../../fixtures/tail/deflated-dmg.zip");
    let (result, source) = local(data);
    assert!(matches!(result.status, Status::Complete), "{result:?}");
    assert_eq!(result.bundle_id.as_deref(), Some("org.doesitarm.fixture"));
    assert!(result.bytes_read <= data.len() as u64);
    // One decode pass to reach the trailer and one to hold the image: the
    // compressed bytes may be requested about twice, not once per jump.
    assert!(
        source.requested <= 3 * data.len() as u64,
        "requested {} of a {} byte file in {} reads",
        source.requested,
        data.len(),
        source.reads
    );
}

#[test]
fn zero_filled_executable_entry_stops_after_the_header() {
    let data = include_bytes!("../../fixtures/tail/zeros-executable.zip");
    let (result, source) = local(data);
    assert!(source.requested <= 2 * data.len() as u64, "{}", source.requested);
    assert!(result.bytes_read <= data.len() as u64);
    assert!(result.decoded_bytes < 8 * 1024 * 1024, "{:?}", result.decoded_bytes);
}

#[test]
fn many_entries_never_read_more_than_the_file_twice() {
    let data = include_bytes!("../../fixtures/tail/many-entries.zip");
    let (result, source) = local(data);
    assert!(source.requested <= 2 * data.len() as u64, "{}", source.requested);
    assert!(result.bytes_read <= data.len() as u64);
}
